/**
 * The emails LibVerse sends: subject, plain text and branded dark HTML for each.
 * Every value from a user (the name) is escaped; codes are 6 digits generated by the server.
 */
const MINUTES = 10;

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[c]));

/**
 * The shared dark layout (tables and inline styles: what email clients render reliably).
 * @param {{ preheader: string, heading: string, intro: string, code?: string, outro: string, footnote: string }} parts
 *   intro / outro / footnote are HTML built from escaped values
 */
const layout = ({ preheader, heading, intro, code, outro, footnote }) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<meta name="supported-color-schemes" content="dark">
<title>${escapeHtml(heading)}</title>
</head>
<body style="margin:0;padding:0;background:#020713;color:#e2e8f0;font-family:Segoe UI,Helvetica,Arial,sans-serif;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#020713;padding:32px 12px;">
<tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#0b1224;border:1px solid #1e293b;border-radius:16px;">
<tr><td style="padding:28px 32px 8px 32px;">
<p style="margin:0;font-size:22px;font-weight:700;letter-spacing:0.2px;color:#ffffff;">Lib<span style="color:#818cf8;">Verse</span></p>
<p style="margin:4px 0 0 0;font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#64748b;">Smart Library Management System</p>
</td></tr>
<tr><td style="padding:20px 32px 0 32px;">
<h1 style="margin:0 0 12px 0;font-size:20px;line-height:1.3;color:#ffffff;">${escapeHtml(heading)}</h1>
<p style="margin:0;font-size:15px;line-height:1.6;color:#cbd5e1;">${intro}</p>
</td></tr>
${code ? `<tr><td align="center" style="padding:24px 32px;">
<div style="display:inline-block;padding:14px 26px;border-radius:12px;background:#111c3a;border:1px solid #4f46e5;font-family:Consolas,Menlo,monospace;font-size:32px;font-weight:700;letter-spacing:10px;color:#ffffff;">${code}</div>
</td></tr>` : ''}
<tr><td style="padding:${code ? '0' : '16px'} 32px 24px 32px;">
<p style="margin:0;font-size:15px;line-height:1.6;color:#cbd5e1;">${outro}</p>
</td></tr>
<tr><td style="padding:16px 32px 28px 32px;border-top:1px solid #1e293b;">
<p style="margin:0;font-size:12px;line-height:1.6;color:#64748b;">${footnote}</p>
</td></tr>
</table>
<p style="margin:16px 0 0 0;font-size:11px;color:#475569;">This is an automatic email from LibVerse. Please don't reply.</p>
</td></tr>
</table>
</body>
</html>`;

const greeting = (name) => `Hi ${name || 'there'},`;

/** Sign-up: confirm the email address */
const verificationEmail = (name, code) => ({
  subject: `${code} is your LibVerse verification code`,
  text: [
    greeting(name),
    '',
    `Your LibVerse verification code is ${code}.`,
    `It expires in ${MINUTES} minutes. Enter it on the sign-up page to confirm your email and open your account.`,
    '',
    'If you did not create a LibVerse account, ignore this email.',
  ].join('\n'),
  html: layout({
    preheader: `Your verification code expires in ${MINUTES} minutes.`,
    heading: 'Confirm your email',
    intro: `${escapeHtml(greeting(name))} welcome to LibVerse. Enter this code to confirm your email address:`,
    code,
    outro: `It expires in ${MINUTES} minutes.`,
    footnote: 'If you did not create a LibVerse account, ignore this email.',
  }),
});

/** Passwordless sign-in: a one-time login code */
const loginCodeEmail = (name, code) => ({
  subject: `${code} is your LibVerse sign-in code`,
  text: [
    greeting(name),
    '',
    `Your LibVerse sign-in code is ${code}.`,
    `It expires in ${MINUTES} minutes and works once. Enter it on the sign-in page.`,
    '',
    'If you did not try to sign in, ignore this email: nobody can sign in without the code.',
  ].join('\n'),
  html: layout({
    preheader: `Your sign-in code expires in ${MINUTES} minutes.`,
    heading: 'Your sign-in code',
    intro: `${escapeHtml(greeting(name))} enter this code on the sign-in page:`,
    code,
    outro: `It expires in ${MINUTES} minutes and works once.`,
    footnote: 'If you did not try to sign in, ignore this email: nobody can sign in without the code.',
  }),
});

/** Forgot password: a reset code */
const passwordResetEmail = (name, code) => ({
  subject: `${code} is your LibVerse password reset code`,
  text: [
    greeting(name),
    '',
    `Your LibVerse password reset code is ${code}.`,
    `It expires in ${MINUTES} minutes. Enter it on the "Forgot password" page to choose a new password.`,
    '',
    'If you did not ask for this, ignore this email: your password stays the same.',
  ].join('\n'),
  html: layout({
    preheader: `Your password reset code expires in ${MINUTES} minutes.`,
    heading: 'Reset your password',
    intro: `${escapeHtml(greeting(name))} enter this code on the "Forgot password" page to choose a new password:`,
    code,
    outro: `It expires in ${MINUTES} minutes.`,
    footnote: 'If you did not ask for this, ignore this email: your password stays the same.',
  }),
});

/** Forgot password for an account created with Google (no password to reset) */
const googleOnlyEmail = (name) => ({
  subject: 'Signing in to LibVerse',
  text: [
    greeting(name),
    '',
    'Someone asked to reset the password of your LibVerse account. Your account uses Google sign-in and',
    'has no password yet, so there is nothing to reset.',
    '',
    'Sign in with the "Sign in with Google" button. If you also want a password, set one in Settings > Security.',
    '',
    'If you did not ask for this, ignore this email.',
  ].join('\n'),
  html: layout({
    preheader: 'Your account signs in with Google.',
    heading: 'Signing in to LibVerse',
    intro: `${escapeHtml(greeting(name))} someone asked to reset the password of your LibVerse account. Your account uses Google sign-in and has no password yet, so there is nothing to reset.`,
    outro: 'Sign in with the <strong style="color:#ffffff;">Sign in with Google</strong> button. If you also want a password, set one in <em>Settings &gt; Security</em>.',
    footnote: 'If you did not ask for this, ignore this email.',
  }),
});

module.exports = { verificationEmail, loginCodeEmail, passwordResetEmail, googleOnlyEmail, escapeHtml };
